    suffix_sum = [0] * (n + 1)
    for i in range(n-1, -1, -1):
        suffix_sum[i] = suffix_sum[i+1] + a[i]

    max_val = 0
    for k in range(n-1):
        current = prefix_squares[k+1] * suffix_sum[k+1]
        if current > max_val:
            max_val = current

    print(max_val)

